45	  postJson<LineItem>('/api/invoices/lineitems/remove', { id });
46	
47	// A line's own amount, and the whole invoice's amount — both DERIVED from qty and unit price, never
48	// stored on the client. The project's invoices list shows the same figure (the server keeps the
49	// invoice's stored amount in step as its lines change).
50	export const lineAmount = (item: LineItem): number => Number(item.qty) * Number(item.unitPrice);
51	
52	export const invoiceTotal = (items: LineItem[]): number =>
53	  items.reduce((sum, item) => sum + lineAmount(item), 0);
