5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // invoices references projects references clients, so H2 refuses to TRUNCATE a parent while
36	        // the FK exists — drop referential integrity for the duration, truncate all, then restore.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        try {
39	            jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
40	            jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
41	            jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
42	            jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
43	            jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
44	            jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
45	            jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
46	            jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
47	        } finally {
48	            jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
49	        }
50	    }
51	
52	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
53	    @PostMapping("/seed")
54	    @SuppressWarnings("unchecked")
55	    public void seed(@RequestBody Map<String, Object> fixture) {
56	        List<Map<String, Object>> clients =
57	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
58	        // Explicit ids from the fixture (the spec asserts rows by these ids), via JdbcTemplate.
59	        for (Map<String, Object> c : clients) {
60	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
61	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
62	        }
63	        List<Map<String, Object>> projects =
64	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
65	        for (Map<String, Object> p : projects) {
66	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
67	                    ((Number) p.get("id")).longValue(), p.get("name"),
68	                    ((Number) p.get("clientId")).longValue());
69	        }
70	        List<Map<String, Object>> contacts =
71	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
72	        for (Map<String, Object> c : contacts) {
73	            jdbc.update(
74	                    "INSERT INTO contacts (id, name, email, contact_role, client_id)"
75	                            + " VALUES (?, ?, ?, ?, ?)",
76	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"),
77	                    c.get("role"), ((Number) c.get("clientId")).longValue());
78	        }
79	        List<Map<String, Object>> invoices =
80	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
81	        for (Map<String, Object> inv : invoices) {
82	            Object status = inv.getOrDefault("status", "DRAFT");
83	            // Dates are optional in the fixture — a spec that only cares about the lifecycle leaves
84	            // them out, so default issued=today / due=+30 days (the same rule CreateInvoice applies).
85	            java.time.LocalDate issued = inv.get("issuedDate") != null
86	                    ? java.time.LocalDate.parse(inv.get("issuedDate").toString())
87	                    : java.time.LocalDate.now();
88	            java.time.LocalDate due = inv.get("dueDate") != null
89	                    ? java.time.LocalDate.parse(inv.get("dueDate").toString())
90	                    : issued.plusDays(30);
91	            // An invoice is built from line items; its amount is the sum of each line's qty times
92	            // unit price. A fixture gives the lines (not a figure), so compute the amount from them
93	            // here — the same derivation CreateLineItem keeps in step on every add. A legacy fixture
94	            // that still supplies an explicit amount (and no lines) is honoured as-is.
95	            List<Map<String, Object>> lineItems =
96	                    (List<Map<String, Object>>) inv.getOrDefault("lineItems", List.of());
97	            java.math.BigDecimal amount;
98	            if (inv.get("amount") != null) {
99	                amount = new java.math.BigDecimal(inv.get("amount").toString());
100	            } else {
101	                amount = java.math.BigDecimal.ZERO;
102	                for (Map<String, Object> li : lineItems) {
103	                    amount = amount.add(new java.math.BigDecimal(li.get("unitPrice").toString())
104	                            .multiply(new java.math.BigDecimal(li.get("qty").toString())));
105	                }
106	            }
107	            jdbc.update(
108	                    "INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
109	                            + " VALUES (?, ?, ?, ?, ?, ?)",
110	                    ((Number) inv.get("id")).longValue(),
111	                    ((Number) inv.get("projectId")).longValue(),
112	                    amount,
113	                    status.toString(),
114	                    java.sql.Date.valueOf(issued),
115	                    java.sql.Date.valueOf(due));
116	            // Insert the invoice's lines with their explicit fixture ids (the spec asserts rows by
117	            // these ids), owned by this invoice.
118	            for (Map<String, Object> li : lineItems) {
119	                jdbc.update(
120	                        "INSERT INTO invoice_line_items"
121	                                + " (id, invoice_id, description, quantity, unit_price)"
122	                                + " VALUES (?, ?, ?, ?, ?)",
123	                        ((Number) li.get("id")).longValue(),
124	                        ((Number) inv.get("id")).longValue(),
125	                        li.get("description"),
126	                        ((Number) li.get("qty")).intValue(),
127	                        new java.math.BigDecimal(li.get("unitPrice").toString()));
128	            }
129	        }
130	        List<Map<String, Object>> tasks =
131	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
132	        for (Map<String, Object> t : tasks) {
133	            // done is optional in the fixture — a spec that only cares a task exists leaves it out,
134	            // so it defaults to not-done (the same state CreateTask would give a fresh task).
135	            boolean done = Boolean.TRUE.equals(t.getOrDefault("done", Boolean.FALSE));
136	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
137	                    ((Number) t.get("id")).longValue(),
138	                    ((Number) t.get("projectId")).longValue(),
139	                    t.get("title"), done);
140	        }
141	        List<Map<String, Object>> tags =
142	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
143	        for (Map<String, Object> tag : tags) {
144	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
145	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
146	        }
147	        // The many-to-many links: which seeded tag sits on which seeded project.
148	        List<Map<String, Object>> projectTags =
149	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
150	        for (Map<String, Object> pt : projectTags) {
151	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
152	                    ((Number) pt.get("projectId")).longValue(),
153	                    ((Number) pt.get("tagId")).longValue());
154	        }
155	    }
156	}
