                    + " VALUES (?, ?, ?, ?, ?)",
            noteId,
            n.get("targetType"),
            ((Number) n.get("targetId")).longValue(),
            n.get("text"),
            at);
    maxNoteId = Math.max(maxNoteId, noteId);
}
